import { afterAll, beforeAll, expect, test } from 'bun:test';
import { chromium, type Browser, type Page, type Route } from 'playwright';
import { execFileSync, spawn, type ChildProcess } from 'node:child_process';
import { mkdirSync, openSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const snapshot = resolve('.temp/feed-focus-candidate');
const evidence = resolve('.temp/feed-rsc-evidence');
const origin = 'http://127.0.0.1:62839';
const pin = 'c3c84ef50757a2d5b5915dac7312175f7b61adc8';
let server: ChildProcess;
let browser: Browser;
let page: Page;
let rscRoute: Route | undefined;
let releaseRsc = () => {};
let releaseFresh = () => {};
let delayFresh = false;
let injectCount = 0;
let refreshCount = 0;
const events: any[] = [];
const feed: any[] = [];
const documents: any[] = [];
const initiators: any[] = [];
const result: any = { events, feed, documents, initiators };
mkdirSync(evidence, { recursive: true });
const mark = (event: string, data: any = {}) => { events.push({ event, elapsed: performance.now(), ...data }); save(); };
const save = () => writeFileSync(`${evidence}/observations.json`, JSON.stringify(result, null, 2));
const git = (...args: string[]) => execFileSync('git', ['-C', snapshot, ...args], { encoding: 'utf8' }).trim();

beforeAll(async () => {
  if (git('rev-parse', 'HEAD') !== pin || git('status', '--porcelain=v1')) throw new Error('Exact clean candidate required');
  result.source = { head: pin, tree: git('rev-parse', 'HEAD^{tree}'), clean: true, snapshot, harness: execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim(), backend: execFileSync('git', ['-C', '/home/edge/projects/rezics/rezics-next/.temp/stack/rezics-dev/backend', 'rev-parse', 'HEAD'], { encoding: 'utf8' }).trim() };
  server = spawn('task', ['--dir', snapshot, 'web:dev', '--', '--port', '62839'], {
    detached: true, stdio: ['ignore', openSync(`${evidence}/web-server.log`, 'a'), openSync(`${evidence}/web-server.log`, 'a')],
    env: { ...process.env, WRANGLER_SEND_METRICS: 'false' },
  });
  let ready = false;
  for (let attempt = 0; attempt < 150; attempt++) {
    try { const response = await fetch(`${origin}/favicon.ico`, { signal: AbortSignal.timeout(2000) }); if (response.status !== 503) { ready = true; break; } } catch {}
    await Bun.sleep(1000);
  }
  if (!ready) throw new Error('Pinned web frontend did not become ready');
  browser = await chromium.launch({ headless: true });
  page = await browser.newPage({ viewport: { width: 1440, height: 1000 }, reducedMotion: 'reduce' });
  page.setDefaultTimeout(60000);
  await page.addInitScript(() => {
    (window as any).feedRscDocumentToken = crypto.randomUUID();
    (window as any).feedRscRequests = [];
    const send = window.fetch;
    window.fetch = Object.assign(async (input: RequestInfo | URL, init?: RequestInit) => {
      const url = input instanceof Request ? input.url : String(input);
      if (url.includes('/api/main/v1/feed')) (window as any).feedRscRequests.push({ url, credentials: init?.credentials, method: init?.method ?? 'GET' });
      return send(input, init);
    }, { preconnect: send.preconnect });
  });
  const cdp = await page.context().newCDPSession(page);
  await cdp.send('Network.enable');
  cdp.on('Network.requestWillBeSent', event => {
    if (new URL(event.request.url).searchParams.has('_rsc')) {
      initiators.push({ url: event.request.url, type: event.type, initiator: event.initiator }); save();
    }
  });
  page.on('request', request => {
    if (request.isNavigationRequest() && request.frame() === page.mainFrame()) {
      documents.push({ url: request.url(), type: request.resourceType(), elapsed: performance.now() }); save();
    }
  });
  page.on('requestfailed', request => {
    if (new URL(request.url()).searchParams.has('_rsc')) mark('rsc-requestfailed', { url: request.url(), error: request.failure()?.errorText });
  });
  page.on('console', message => {
    if (message.type() === 'error' && /RSC|Failed to fetch|navigation/i.test(message.text())) mark('browser-console', { text: message.text().slice(0, 1200) });
  });
  page.on('pageerror', error => mark('pageerror', { message: error.message }));
  await page.route('**/api/main/v1/feed?**', async route => {
    const url = new URL(route.request().url());
    if (url.searchParams.has('cursor') && injectCount === 0) {
      injectCount++;
      feed.push({ cursor: true, url: url.href, status: 409, injected: true });
      await route.fulfill({ status: 409, contentType: 'application/json', body: JSON.stringify({ code: 'cursor_conflict' }) });
      mark('one-cursor-409-injected'); return;
    }
    const held = delayFresh && !url.searchParams.has('cursor');
    let gate = Promise.resolve();
    if (held) { delayFresh = false; gate = new Promise<void>(resolve => { releaseFresh = resolve; }); }
    const response = await route.fetch({ timeout: 60000 });
    const body = await response.body();
    const entry: any = { cursor: url.searchParams.has('cursor'), requestCursor: url.searchParams.get('cursor'), url: url.href, status: response.status(), retainedResponse: true };
    if (response.ok()) {
      const data = JSON.parse(body.toString());
      entry.nextCursor = data.nextCursor; entry.projection = data.projection;
      writeFileSync(`${evidence}/genuine-page-${feed.length}.json`, body);
    }
    if (held) { mark('genuine-first-page-held', { status: response.status() }); await gate; }
    feed.push(entry); save(); await route.fulfill({ response, body });
  });
  await page.route('**/*', async route => {
    const request = route.request();
    const headers = await request.allHeaders();
    const requestUrl = new URL(request.url());
    if (headers.rsc !== '1' || headers['next-router-prefetch'] || requestUrl.pathname !== '/en' || requestUrl.searchParams.get('lang') !== 'en' || !result.routerInvokedAt || rscRoute) return route.fallback();
    rscRoute = route;
    const boundedGate = new Promise<void>(resolve => { releaseRsc = resolve; });
    result.rsc = { url: request.url(), method: request.method(), resourceType: request.resourceType(), isNavigationRequest: request.isNavigationRequest(), headers: Object.fromEntries(Object.entries(headers).filter(([key]) => ['rsc', 'next-router-state-tree', 'next-url', 'next-router-prefetch', 'next-router-segment-prefetch', 'accept'].includes(key))) };
    mark('actual-rsc-held');
    const timer = setTimeout(releaseRsc, 30000);
    await boundedGate;
    clearTimeout(timer);
    mark('rsc-abort-issued', { errorCode: 'failed', controlledNetworkFault: true });
    await route.abort('failed');
    mark('rsc-abort-completed');
  });
}, 180000);

afterAll(async () => {
  releaseFresh(); releaseRsc(); save();
  await page?.unrouteAll({ behavior: 'wait' });
  await browser?.close();
  if (server?.pid) { try { process.kill(-server.pid, 'SIGTERM'); } catch {} }
  result.finalSource = { head: git('rev-parse', 'HEAD'), tree: git('rev-parse', 'HEAD^{tree}'), clean: !git('status', '--porcelain=v1') }; save();
});

test('one Refresh recovers genuine cursor pages when an actual Next router RSC request is held and aborted', async () => {
  await page.goto(`${origin}/en?lang=en`, { waitUntil: 'domcontentloaded', timeout: 120000 });
  const alert = page.getByRole('alert').filter({ hasText: 'The feed changed while you were reading' });
  await alert.waitFor();
  const before = await page.evaluate(() => ({ url: location.href, language: document.documentElement.lang, token: (window as any).feedRscDocumentToken }));
  result.before = before;
  result.routerInvokedAt = performance.now();
  await page.evaluate(() => {
    if (typeof (window as any).next?.router?.refresh !== 'function') throw new Error('Mounted Next router refresh is unavailable');
    (window as any).next.router.refresh();
  });
  for (let i = 0; i < 100 && !rscRoute; i++) await Bun.sleep(100);
  expect(!!rscRoute).toBe(true);
  expect(result.rsc.headers.rsc).toBe('1');
  expect(result.rsc.headers.accept).toBe('text/x-component');
  expect(new URL(result.rsc.url).pathname).toBe('/en');
  expect(new URL(result.rsc.url).searchParams.get('lang')).toBe('en');
  expect(initiators.some(entry => entry.url === result.rsc.url && entry.initiator.stack?.callFrames.some((frame: any) => frame.functionName === 'navigateRsc' && frame.url.includes('/vinext/dist/server/app-browser-entry.js')))).toBe(true);
  expect(result.rsc.isNavigationRequest).toBe(false);
  const refresh = alert.getByRole('button', { name: 'Refresh', exact: true });
  await refresh.focus(); delayFresh = true; refreshCount++;
  await page.keyboard.press('Enter');
  await page.getByText('Refreshing posts…', { exact: true }).waitFor();
  result.pending = await page.evaluate(() => {
    (window as any).feedRscPendingFocus = document.activeElement;
    return { tag: document.activeElement?.tagName, role: document.activeElement?.getAttribute('role'), name: document.activeElement?.getAttribute('aria-label'), busy: document.activeElement?.getAttribute('aria-busy'), token: (window as any).feedRscDocumentToken };
  });
  mark('one-refresh-pending', { refreshCount });
  await page.screenshot({ path: `${evidence}/pending-rsc-held-1440.png` });
  expect(result.pending).toEqual({ tag: 'DIV', role: 'group', name: 'Posts', busy: 'true', token: before.token });
  releaseRsc();
  for (let i = 0; i < 100 && !events.some(event => event.event === 'rsc-requestfailed'); i++) await Bun.sleep(50);
  expect(events.some(event => event.event === 'rsc-requestfailed')).toBe(true);
  mark('release-genuine-recovery-after-rsc-abort'); releaseFresh();
  // Keep observing the original outcome after the fault; a reload is a failure, never hidden or intercepted.
  for (let i = 0; i < 200; i++) {
    if (documents.length > 1) break;
    const rows = await page.locator('[data-feed-item]').count();
    if (rows >= 6 && feed.filter(entry => !entry.injected).length >= 3) break;
    await page.waitForTimeout(100);
  }
  await page.waitForTimeout(1500);
  const after = await page.evaluate(() => ({ url: location.href, language: document.documentElement.lang, token: (window as any).feedRscDocumentToken, requests: (window as any).feedRscRequests,
    focus: { same: document.activeElement === (window as any).feedRscPendingFocus, tag: document.activeElement?.tagName, role: document.activeElement?.getAttribute('role'), name: document.activeElement?.getAttribute('aria-label'), busy: document.activeElement?.getAttribute('aria-busy') },
    ids: Array.from(document.querySelectorAll('[data-feed-item]')).map(el => el.getAttribute('data-feed-item')) }));
  result.after = after; result.refreshCount = refreshCount; result.injectCount = injectCount;
  result.remainingAlerts = await alert.count();
  result.clientRecovered = after.ids.length >= 6 && new Set(after.ids).size === after.ids.length && result.remainingAlerts === 0;
  await page.screenshot({ path: `${evidence}/after-rsc-abort-1440.png` }); save();
  expect(injectCount).toBe(1);
  expect(refreshCount).toBe(1);
  expect(documents).toHaveLength(1);
  expect(after.token).toBe(before.token);
  expect(after.url).toBe(before.url);
  expect(after.language).toBe(before.language);
  expect(after.ids.length).toBeGreaterThanOrEqual(6);
  expect(new Set(after.ids).size).toBe(after.ids.length);
  expect(result.remainingAlerts).toBe(0);
  expect(after.requests.every((request: any) => request.credentials === 'omit' && !new URL(request.url, origin).searchParams.has('actingSubject'))).toBe(true);
  expect(feed.filter(entry => !entry.injected).every(entry => entry.status === 200)).toBe(true);
  expect(feed.filter(entry => !entry.injected).length).toBeGreaterThanOrEqual(3);
  expect(after.focus).toEqual({ same: true, tag: 'DIV', role: 'group', name: 'Posts', busy: 'false' });
}, 180000);
